use super::*;
use serde_json::{json,Value};
use kfc_kfc_alpha::kfc::xpxml::writer::r#impl::MemoryXmlWriter::MemoryXmlWriter;
use crate::cn::wps::moss::{engine::grid::KmoCellValueStore::KmoCellValueStore,filefmt::biff8::record::common::{UnicodeString::UnicodeString,FormatRun::FormatRun}};
fn font(p:&Value)->Rc<KmoFont>{let f=KmoFont::KmoFont();f.setBoldWeight(p["bold"].as_i64().unwrap()as i16);f.setItalic(p["italic"].as_bool().unwrap());f.setStrikeout(p["strike"].as_bool().unwrap());f.setCharset(p["charset"].as_i64().unwrap()as i8);f.setUnderline(p["underline"].as_i64().unwrap()as i8);f.setSuperSubScript(p["super"].as_i64().unwrap()as i16);f.setFontHeight(p["height"].as_i64().unwrap()as i16);f.setColorPaletteIndex(p["color"].as_i64().unwrap()as i32);f.setFontName(p["name"].as_str().unwrap().into());Rc::new(f)}
#[test]
fn original_android_fonts_colors_and_string_iterator(){
    let p=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/labels-r0b33");let j:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let mut fonts=vec![];
    for case in input["fonts"].as_array().unwrap(){let mut w=MemoryXmlWriter::new();FontsLabel::writeFontImpl(&mut w,&font(case));fonts.push(json!({"input":case,"xml":w.getString()}));}
    let underlines:Vec<_>=(-128..=127).map(|i|FontsLabel::getUnderline(i as i8)).collect();let colors:Vec<_>=input["colors"].as_array().unwrap().iter().map(|i|{let v=i.as_i64().unwrap()as i32;json!({"value":v,"hex":ValueHelper::toHexColor(v),"palette":ColorToolKit::isPaletteIndex(v),"valid":ColorToolKit::isValidColor(v)})}).collect();
    let mut label=FontsLabel::FontsLabel();let first=font(&input["fonts"][0]);let mut history=vec![];for(i,index)in [4,4,-1,0,4,i32::MAX,-1].into_iter().enumerate(){let id=label.addForWrite(if i%3==0{None}else{Some(first.clone())},index);if i==4{first.setFontName("changed<&>\n".into());}let mut w=MemoryXmlWriter::new();label.write(&mut w);history.push(json!({"id":id,"xml":w.getString()}));}
    let mut store=KmoCellValueStore::KmoCellValueStore();let mut rich=UnicodeString::new("富😀text".into());rich.resetFormatRuns(vec![FormatRun::new(1,2),FormatRun::new(3,5)]);let rich=Rc::new(rich);for value in [Rc::new(UnicodeString::new("".into())),Rc::new(UnicodeString::new("plain<&>\n\0".into())),rich.clone(),Rc::new(UnicodeString::new("same".into())),Rc::new(UnicodeString::new("same".into()))]{store.addUnicodeString(Some(value));}let mut it=store.getStrStoreIterator();let mut rows=vec![];while it.hasNext(){let value=it.next();let runs:Vec<_>=value.getFormatRuns().iter().map(|r|json!([r.getCharacterPos(),r.getFontIndex()])).collect();rows.push(json!({"text":value.getString(),"runs":runs,"sameRich":Rc::ptr_eq(&value,&rich)}));it.remove();}let beyond=it.next();let hasNext=it.hasNext();drop(it);let strings=json!({"rows":rows,"hasNext":hasNext,"beyond":beyond.getString(),"count":store.getUniqueCount()});
    let actual=json!({"fonts":fonts,"underlines":underlines,"colors":colors,"history":history,"strings":strings});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();assert_eq!(actual,j);
}
